contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // run a single invocation that calls buy and checks the invariant described above
    function run(uint256[] calldata tokenIds, uint256[] calldata tokenWeights, bytes32[] calldata proofBytes, bool[] calldata flags, uint256 ethAmount) public payable {
        // build a MerkleMultiProof struct compatible with c.sumWeightsAndValidateProof
        C.MerkleMultiProof memory proof;
        proof.proof = proofBytes;
        proof.flags = flags;

        // read observable before-values
        uint256 beforeVirtualBase = c.virtualBaseTokenReserves();
        uint256 factoryBefore = address(Factory(payable(c.factory())).address(this)).balance; // dummy read; will not compile if used, so avoid using
        // Instead observe factory balance after by reading address(c.factory()).balance via address
        address factoryAddr = c.factory();
        uint256 factoryBalBefore = factoryAddr.balance;
        uint256 cBalBefore = address(c).balance;

        // perform the buy call, capturing revert
        bool reverted;
        uint256 netInputAmount;
        uint256 feeAmount;
        uint256 protocolFeeAmount;
        try c.buy{value: ethAmount}(tokenIds, tokenWeights, proof) returns (uint256 n, uint256 f, uint256 p) {
            reverted = false;
            netInputAmount = n;
            feeAmount = f;
            protocolFeeAmount = p;
        } catch {
            reverted = true;
        }

        // read after-values
        uint256 afterVirtualBase = c.virtualBaseTokenReserves();
        uint256 factoryBalAfter = factoryAddr.balance;
        uint256 cBalAfter = address(c).balance;

        // If call succeeded (not reverted) then virtualBaseTokenReserves must have increased by netInputAmount - feeAmount - protocolFeeAmount
        // If call reverted, factory balance must be unchanged (no protocol fee sent) and c balance unchanged
        if (!reverted) {
            // Avoid underflow: compare as before + delta == after
            uint256 expectedIncrease = 0;
            // netInputAmount includes royalty additions in function; but contract increases by (netInputAmount - fee - protocolFee)
            // compute expectedIncrease = netInputAmount - feeAmount - protocolFeeAmount
            expectedIncrease = netInputAmount - feeAmount - protocolFeeAmount;
            assert(afterVirtualBase == beforeVirtualBase + expectedIncrease);
        } else {
            // when reverted, ensure no protocol fee left factory nor did c receive ETH
            assert(factoryBalAfter == factoryBalBefore && cBalAfter == cBalBefore);
        }
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single public entry performing a buy (possibly with ETH) and asserting the invariant
    function run(uint256[] calldata tokenIds, uint256[] calldata tokenWeights, bytes32[] calldata proofBytes, bool[] calldata flags, uint256 ethAmount) public payable {
        // build MerkleMultiProof expected by c
        C.MerkleMultiProof memory proof;
        proof.proof = proofBytes;
        proof.flags = flags;

        // observe before-values
        uint256 beforeVirtualBase = c.virtualBaseTokenReserves();
        address factoryAddr = c.factory();
        uint256 beforeFactoryBal = factoryAddr.balance;
        uint256 beforePoolBal = address(c).balance;

        // perform buy, capturing revert and returned values
        bool reverted;
        uint256 netInputAmount;
        uint256 feeAmount;
        uint256 protocolFeeAmount;
        // ensure this contract has enough ETH to forward if needed
        if (ethAmount > 0) {
            require(address(this).balance >= ethAmount, "insufficient test balance");
        }

        try c.buy{value: ethAmount}(tokenIds, tokenWeights, proof) returns (uint256 n, uint256 f, uint256 p) {
            reverted = false;
            netInputAmount = n;
            feeAmount = f;
            protocolFeeAmount = p;
        } catch {
            reverted = true;
        }

        // observe after-values
        uint256 afterVirtualBase = c.virtualBaseTokenReserves();
        uint256 afterFactoryBal = factoryAddr.balance;
        uint256 afterPoolBal = address(c).balance;

        // General rule:
        // - If buy succeeded: virtualBaseTokenReserves increases exactly by (netInputAmount - feeAmount - protocolFeeAmount).
        // - If buy reverted: pool ETH balance and factory balance are unchanged.
        assert(
            (!reverted && afterVirtualBase == beforeVirtualBase + (netInputAmount - feeAmount - protocolFeeAmount))
            || (reverted && afterPoolBal == beforePoolBal && afterFactoryBal == beforeFactoryBal)
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single public entry: attempt to initialize the pool and check observable effects
    function run(
        address baseToken,
        address nft,
        uint128 virtualBaseTokenReserves,
        uint128 virtualNftReserves,
        uint56 changeFee,
        uint16 feeRate,
        bytes32 merkleRoot,
        bool useStolenNftOracle,
        bool payRoyalties
    ) public payable {
        // require a reasonable bound so arithmetic in C won't overflow in the environment
        require(feeRate <= 5000, "feeRate must be <= 5000 for this property");

        // Read initial initialized flag
        bool beforeInitialized = c.initialized();

        // Call initialize and capture whether it reverts
        bool reverted;
        try c.initialize(
            baseToken,
            nft,
            virtualBaseTokenReserves,
            virtualNftReserves,
            changeFee,
            feeRate,
            merkleRoot,
            useStolenNftOracle,
            payRoyalties
        ) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read after-values for public getters
        bool afterInitialized = c.initialized();
        address afterBaseToken = c.baseToken();
        address afterNft = c.nft();
        uint128 afterVirtualBase = c.virtualBaseTokenReserves();
        uint128 afterVirtualNft = c.virtualNftReserves();
        uint56 afterChangeFee = c.changeFee();
        uint16 afterFeeRate = c.feeRate();
        bytes32 afterMerkle = c.merkleRoot();
        bool afterUseOracle = c.useStolenNftOracle();
        bool afterPayRoyalties = c.payRoyalties();

        // General rule (single assert):
        // If contract was not initialized before the call, initialize MUST succeed (not revert), set initialized==true,
        // and the public getters must equal the parameters passed.
        // If it was already initialized before the call, initialize MUST revert and state must remain unchanged (initialized stays true).
        assert(
            (!beforeInitialized && !reverted
                && afterInitialized == true
                && afterBaseToken == baseToken
                && afterNft == nft
                && afterVirtualBase == virtualBaseTokenReserves
                && afterVirtualNft == virtualNftReserves
                && afterChangeFee == changeFee
                && afterFeeRate == feeRate
                && afterMerkle == merkleRoot
                && afterUseOracle == useStolenNftOracle
                && afterPayRoyalties == payRoyalties)
            || (
                beforeInitialized && reverted && afterInitialized == beforeInitialized
            )
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single public entry: try calling initialize and assert the general invariant described above.
