        address baseToken,
        address nft,
        uint128 virtualBaseTokenReserves,
        uint128 virtualNftReserves,
        uint56 changeFee,
        uint16 feeRate,
        bytes32 merkleRoot,
        bool useStolenNftOracle,
        bool payRoyalties
    ) public payable {
        // Only precondition on parameters: feeRate must be within allowed maximum domain to avoid intentional FeeRateTooHigh revert when testing the uninitialized path.
        // We still allow passing >5000 to exercise the revert-on-invalid-params branch when uninitialized.
        require(feeRate <= 60000, "feeRate bound");

        // Observe state before the call via public getters
        bool beforeInitialized = c.initialized();
        address beforeBaseToken = c.baseToken();
        address beforeNft = c.nft();
