        uint128 beforeVirtualNft = c.virtualNftReserves();
        uint56 beforeChangeFee = c.changeFee();
        uint16 beforeFeeRate = c.feeRate();
        bytes32 beforeMerkle = c.merkleRoot();
        bool beforeUseOracle = c.useStolenNftOracle();
        bool beforePayRoyalties = c.payRoyalties();

        // Attempt initialize and capture whether it reverted
        bool reverted;
        try c.initialize(
            baseToken,
            nft,
            virtualBaseTokenReserves,
            virtualNftReserves,
            changeFee,
            feeRate,
            merkleRoot,
            useStolenNftOracle,
            payRoyalties
