        //   then initialized must become true and all public getters must equal the supplied parameters.
        // - If the pool was already initialized before the call, initialize MUST revert and state must be unchanged.
        // - If the pool was not initialized before the call but initialize reverted, state must remain unchanged.
        assert(
            (
                !beforeInitialized && !reverted
                    && afterInitialized == true
                    && afterBaseToken == baseToken
                    && afterNft == nft
                    && afterVirtualBase == virtualBaseTokenReserves
                    && afterVirtualNft == virtualNftReserves
                    && afterChangeFee == changeFee
                    && afterFeeRate == feeRate
                    && afterMerkle == merkleRoot
                    && afterUseOracle == useStolenNftOracle
                    && afterPayRoyalties == payRoyalties
            )
            || (
                beforeInitialized && reverted
                    && afterInitialized == beforeInitialized
                    && afterBaseToken == beforeBaseToken
                    && afterNft == beforeNft
                    && afterVirtualBase == beforeVirtualBase
                    && afterVirtualNft == beforeVirtualNft
                    && afterChangeFee == beforeChangeFee
                    && afterFeeRate == beforeFeeRate
                    && afterMerkle == beforeMerkle
                    && afterUseOracle == beforeUseOracle
                    && afterPayRoyalties == beforePayRoyalties
            )
            || (
                !beforeInitialized && reverted
                    && afterInitialized == beforeInitialized
                    && afterBaseToken == beforeBaseToken
                    && afterNft == beforeNft
                    && afterVirtualBase == beforeVirtualBase
                    && afterVirtualNft == beforeVirtualNft
                    && afterChangeFee == beforeChangeFee
                    && afterFeeRate == beforeFeeRate
                    && afterMerkle == beforeMerkle
                    && afterUseOracle == beforeUseOracle
                    && afterPayRoyalties == beforePayRoyalties
            )
        );
    }

    receive() external payable {}
